CREATE TABLE IF NOT EXISTS onorc_portability (id BIGSERIAL PRIMARY KEY, reference_number VARCHAR(50) NOT NULL UNIQUE, ration_card_number VARCHAR(100) NOT NULL, home_state VARCHAR(150) NOT NULL, home_district VARCHAR(150) NOT NULL, destination_state VARCHAR(150) NOT NULL, destination_district VARCHAR(150) NOT NULL, fps_name VARCHAR(255), fps_code VARCHAR(100), status VARCHAR(50) NOT NULL, requested_by VARCHAR(255) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE INDEX IF NOT EXISTS idx_onorc_requested_by ON onorc_portability(requested_by); CREATE INDEX IF NOT EXISTS idx_onorc_reference ON onorc_portability(reference_number);
